from itertools import product
from hashlib import sha256

R,Q=(5,6); rect=(2,2)
def deg(x): return sum(x)
def key(x): return ''.join(map(str,x))
def contains(x,y): return all((x[t] if t<len(x) else 0)>=v for t,v in enumerate(y))
def parts_rec(mx,slots,prefix,out):
    if slots==0:
        z=tuple(a for a in prefix if a); out.append(z); return
    for a in range(mx,-1,-1): parts_rec(a,slots-1,prefix+[a],out)
allp=[]; parts_rec(Q,R,[],allp)
cols=sorted([x for x in allp if contains(x,rect)],key=lambda x:(deg(x),x))
ci={x:i for i,x in enumerate(cols)}
def horiz(mu,nu):
    if deg(nu)<=deg(mu) or not contains(nu,mu): return False
    for t in range(1,R):
        if nu[t] > (mu[t-1] if t-1<len(mu) else 0): return False
    return True
rows=[]
for mu in cols:
  for k in range(1,Q+1):
    ts=[nu for nu in cols if deg(nu)==deg(mu)+k and horiz(mu,nu)]
    if ts: rows.append((mu,k,tuple(ts)))
rows.sort(key=lambda z:(deg(z[0])+z[1],z[0],z[1]))
assert len(cols)==431 and len(rows)==2130
families={
 'F1':[(2,2),(3,2),(3,3),(4,2),(4,3),(5,2),(4,4),(5,3),(5,4),(5,5)],
 'F2':[(2,2),(2,2,1),(2,2,1,1),(2,2,2),(2,2,1,1,1),(2,2,2,1),(2,2,2,1,1),(2,2,2,2),(2,2,2,2,1),(2,2,2,2,2)]}

def certify(free):
 free=set(free); selected=[]; pivots=[]; basis=[]
 for D in range(0,R*Q+1):
  cD=[c for c in cols if deg(c)==D]; comp=[c for c in cD if c not in free]
  old=len(selected)
  # unit-pivot row reduction of the degree-D complement matrix
  for ri,(mu,k,ts) in enumerate(rows):
   if deg(mu)+k!=D: continue
   v={x:1 for x in ts}; comb={ri:1}
   for p,b,bc in basis:
    z=v.get(p,0)
    if z:
     for x,a in b.items():
      v[x]=v.get(x,0)-z*a
      if not v[x]: del v[x]
     for x,a in bc.items():
      comb[x]=comb.get(x,0)-z*a
      if not comb[x]: del comb[x]
   choices=[x for x in comp if abs(v.get(x,0))==1]
   if choices:
    p=choices[0]; s=v[p]
    if s==-1:
     v={x:-a for x,a in v.items()}; comb={x:-a for x,a in comb.items()}
    basis.append((p,v,comb)); pivots.append(p); selected.append(ri)
  assert len(selected)-old==len(comp),(D,len(selected)-old,len(comp))
 # reduce every raw row by the triangular unit-pivot basis
 cert=[]
 for ri,(mu,k,ts) in enumerate(rows):
  v={x:1 for x in ts}; comb={ri:1}
  for p,b,bc in basis:
   z=v.get(p,0)
   if z:
    for x,a in b.items():
     v[x]=v.get(x,0)-z*a
     if not v[x]: del v[x]
    for x,a in bc.items():
     comb[x]=comb.get(x,0)-z*a
     if not comb[x]: del comb[x]
  assert not v,(ri,v) # exact integral reduction to selected raw rows
  cert.append(tuple(sorted(comb.items())))
 assert len(selected)==421 and set(pivots)==set(cols)-free
 # Selected raw rows, pivot labels, all raw-row coefficient vectors
 payload=repr((tuple(selected),tuple(key(x) for x in pivots),tuple(cert))).encode()
 return sha256(payload).hexdigest(), selected, pivots
for name,free in families.items():
 h,sel,piv=certify(free)
 print(name,'free='+','.join(key(x) for x in free),'selected='+str(len(sel)),
       'minor_det=+/-1','all_2130_integral_reductions_verified','certificate_sha256='+h)
 print(name,'first_20_pivots='+','.join(key(x) for x in piv[:20]))
